// Kit parity: the Unity KitBuilder must make exactly the parts the web game's buildKit() makes
// (fixtures/kit-fixture.json, generated by running buildKit itself): same sockets, shapes,
// materials and transforms, for every hero, with and without gear, heroes and Hollow enemies.
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Sigilbound.Core;

static class KitTests
{
    static Action<bool, string> Check;

    sealed class Flat { public string Kind; public KitMat Mat; public Mat4 M; }

    // Static parts in preorder (live children of the socket root skipped), in socket space.
    static List<Flat> FlatStatic(KitNode root, bool skipLive)
    {
        var list = new List<Flat>();
        void Walk(KitNode n, Mat4 parent, bool isRoot)
        {
            if (!isRoot && skipLive && n.Live != null) return;
            var m = isRoot ? parent : parent * Mat4.From(n.Local);
            if (n.HasGeometry) list.Add(new Flat { Kind = n.Mesh != null ? n.Mesh.Name : n.Shape, Mat = n.Mat, M = m });
            foreach (var c in n.Children) Walk(c, m, false);
        }
        Walk(root, Mat4.Identity(), true);
        return list;
    }

    static GearLook GearFrom(object o)
    {
        if (!(o is Dictionary<string, object> d)) return null;
        GearLook.Item I(string k) => d.TryGetValue(k, out var v) && v is Dictionary<string, object> x ? new GearLook.Item { R = Json.Int(x, "r"), S = Json.Str(x, "s") } : null;
        return new GearLook { Weapon = I("weapon"), Helm = I("helm"), Chest = I("chest"), Boots = I("boots") };
    }

    static bool Close(double a, double b) => Math.Abs(a - b) < 3e-5;

    static string ComparePart(Flat mine, object theirs)
    {
        string kind = Json.Str(theirs, "kind");
        if (mine.Kind != kind) return $"shape {mine.Kind} vs {kind}";
        var mat = Json.Obj(theirs, "mat");
        if (mine.Mat.Finish.ToString() != Json.Str(mat, "finish") || mine.Mat.Color != Json.Str(mat, "color") || !Close(mine.Mat.Opacity, Json.Num(mat, "opacity", 1)))
            return $"{kind} material {mine.Mat.Finish} {mine.Mat.Color} {mine.Mat.Opacity} vs {Json.Str(mat, "finish")} {Json.Str(mat, "color")} {Json.Num(mat, "opacity", 1)}";
        var m = Json.Arr(theirs, "m");
        for (int r = 0; r < 4; r++)
            for (int c = 0; c < 4; c++)
                if (!Close(mine.M.M[r * 4 + c], (double)m[c * 4 + r])) return $"{kind} transform [{r},{c}] {mine.M.M[r * 4 + c]:0.#####} vs {(double)m[c * 4 + r]}";
        return null;
    }

    public static void Run(Action<bool, string> check)
    {
        Check = check;
        Console.WriteLine("\nKit (weapons, headgear, faces, robes, capes, gear) vs the web's buildKit:");
        var cases = (List<object>)Json.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "fixtures", "kit-fixture.json")));
        int builds = 0, okBuilds = 0, parts = 0; var errors = new List<string>();
        foreach (var c in cases)
        {
            builds++;
            string id = Json.Str(c, "id"); bool hollow = Json.Bool(c, "hollow");
            ((Dictionary<string, object>)c).TryGetValue("gear", out var gearObj);
            var gear = GearFrom(gearObj);
            var mine = KitBuilder.Build(id, hollow, gear, 0.9);
            var theirs = Json.Arr(c, "sockets");
            string label = $"{id}{(hollow ? " (hollow)" : "")}{(gear == null ? "" : " gear " + gear.Key)}";
            string err = null;
            var mySlots = mine.Select(s => s.Slot).OrderBy(x => x, StringComparer.Ordinal).ToList();
            var theirSlots = theirs.Select(s => Json.Str(s, "slot")).OrderBy(x => x, StringComparer.Ordinal).ToList();
            if (!mySlots.SequenceEqual(theirSlots)) err = $"sockets [{string.Join(",", mySlots)}] vs [{string.Join(",", theirSlots)}]";
            foreach (var ts in theirs)
            {
                if (err != null) break;
                var s = mine.First(x => x.Slot == Json.Str(ts, "slot"));
                bool boneMode = Json.Str(ts, "mode") == "bone";
                if ((s.Mode == SocketMode.Bone) != boneMode || s.Bone != Json.Str(ts, "bone")) { err = $"{s.Slot}: mode/bone"; break; }
                var tp = Json.Arr(ts, "pos");
                if (!Close(s.Pos.X, (double)tp[0]) || !Close(s.Pos.Y, (double)tp[1]) || !Close(s.Pos.Z, (double)tp[2])) { err = $"{s.Slot}: socket position"; break; }
                if (Json.Arr(ts, "dir") is List<object> td && (!s.Dir.HasValue || !Close(s.Dir.Value.X, (double)td[0]) || !Close(s.Dir.Value.Y, (double)td[1]) || !Close(s.Dir.Value.Z, (double)td[2]))) { err = $"{s.Slot}: grip direction"; break; }
                if (!Close(s.Roll, Json.Num(ts, "roll"))) { err = $"{s.Slot}: roll"; break; }
                if (!Close(s.ScaleMul, Json.Num(ts, "scale", 1))) { err = $"{s.Slot}: scale {s.ScaleMul} vs {Json.Num(ts, "scale")}"; break; }
                var q = Json.Arr(ts, "q"); var myQ = s.Basis ?? Quat.Identity;
                if (!(Close(myQ.X, (double)q[0]) && Close(myQ.Y, (double)q[1]) && Close(myQ.Z, (double)q[2]) && Close(myQ.W, (double)q[3]))) { err = $"{s.Slot}: socket rotation"; break; }
                var flat = FlatStatic(s.Root, true); var tparts = Json.Arr(ts, "parts");
                if (flat.Count != tparts.Count) { err = $"{s.Slot}: {flat.Count} parts vs {tparts.Count}"; break; }
                for (int i = 0; i < flat.Count && err == null; i++) { var e = ComparePart(flat[i], tparts[i]); if (e != null) err = $"{s.Slot} part {i}: {e}"; }
                parts += flat.Count;
                var lives = s.Root.Children.Where(n => n.Live != null).ToList(); var tl = Json.Arr(ts, "live");
                if (lives.Count != tl.Count) { err = $"{s.Slot}: {lives.Count} live parts vs {tl.Count}"; break; }
                for (int i = 0; i < lives.Count && err == null; i++)
                {
                    var ln = lives[i]; var t = tl[i];
                    var lp = Json.Arr(t, "pos"); var ls = Json.Arr(t, "scale"); var lq = Json.Arr(t, "q"); var rq = ln.Rotation;
                    if (!Close(ln.Pos.X, (double)lp[0]) || !Close(ln.Pos.Y, (double)lp[1]) || !Close(ln.Pos.Z, (double)lp[2]) || !Close(ln.Scale.X, (double)ls[0]) || !Close(ln.Scale.Y, (double)ls[1]) || !Close(ln.Scale.Z, (double)ls[2])
                        || !(Close(rq.X, (double)lq[0]) && Close(rq.Y, (double)lq[1]) && Close(rq.Z, (double)lq[2]) && Close(rq.W, (double)lq[3]))) { err = $"{s.Slot} live {i}: transform"; break; }
                    var lf = FlatStatic(ln, false); var ltp = Json.Arr(t, "parts");
                    if (lf.Count != ltp.Count) { err = $"{s.Slot} live {i}: {lf.Count} parts vs {ltp.Count}"; break; }
                    for (int k = 0; k < lf.Count && err == null; k++)
                    {
                        // Live parts are relative to the live node itself (its own transform removed).
                        var e = ComparePart(lf[k], ltp[k]); if (e != null) err = $"{s.Slot} live {i} part {k}: {e}";
                    }
                    parts += lf.Count;
                }
            }
            if (err == null) okBuilds++; else errors.Add($"{label}: {err}");
        }
        foreach (var e in errors.Take(8)) Console.WriteLine("   " + e);
        Check(okBuilds == builds, $"kit matches buildKit() part for part in {okBuilds}/{builds} builds ({parts} parts: shapes, materials, transforms)");

        // Baking merges each socket into one mesh per material; budget check on a fully geared hero.
        var full = KitBuilder.Build("seraphine", false, new GearLook { Weapon = new GearLook.Item { R = 5, S = "keen" }, Helm = new GearLook.Item { R = 5, S = "keen" }, Chest = new GearLook.Item { R = 5, S = "keen" }, Boots = new GearLook.Item { R = 5, S = "keen" } });
        int tris = KitBuilder.Triangles(full), mats = full.SelectMany(s => KitBuilder.Bake(s.Root).ByMat.Keys).Distinct().Count();
        Check(tris > 1000 && tris < 60000 && mats < 30, $"a Mythic-geared hero's kit: {tris} triangles in {mats} distinct materials");
        var hollowKit = KitBuilder.Build("hask", true, null);
        Check(!hollowKit.SelectMany(s => s.Root.All()).Any(n => n.Mat != null && n.Mat.Color == "#fbf6ee"), "Hollow enemies get no faces (as on the web)");
    }
}
